import static org.junit.jupiter.api.Assertions.assertEquals;

public class BasicContentHandlerFactory_parseHandlerType_3_0_Test {

    @Test
    public void testParseHandlerType_withNullHandlerTypeName() {
        String handlerTypeName = null;
        BasicContentHandlerFactory.HANDLER_TYPE defaultType = BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN;
        BasicContentHandlerFactory.HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(handlerTypeName, defaultType);
        assertEquals(defaultType, result);
    }

    @Test
    public void testParseHandlerType_withValidHandlerTypeName() {
        String handlerTypeName = "xml";
        BasicContentHandlerFactory.HANDLER_TYPE defaultType = BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN;
        BasicContentHandlerFactory.HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(handlerTypeName, defaultType);
        assertEquals(BasicContentHandlerFactory.HANDLER_TYPE.XML, result);
    }

    @Test
    public void testParseHandlerType_withInvalidHandlerTypeName() {
        String handlerTypeName = "invalid";
        BasicContentHandlerFactory.HANDLER_TYPE defaultType = BasicContentHandlerFactory.HANDLER_TYPE.MARKDOWN;
        BasicContentHandlerFactory.HANDLER_TYPE result = BasicContentHandlerFactory.parseHandlerType(handlerTypeName, defaultType);
        assertEquals(defaultType, result);
    }
}
